def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separate the two panels at the uniform divider.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panels = (grid[:r], grid[r + 1:])
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                panels = (
                    [row[:c] for row in grid],
                    [row[c + 1:] for row in grid],
                )
                break

    from collections import Counter

    def dominant(panel):
        return Counter(v for row in panel for v in row).most_common()

    counts = [dominant(p) for p in panels]
    # The patterned panel has one strongly dominant color and sparse marks.
    fractions = [
        counts[i][0][1] / sum(n for _, n in counts[i])
        for i in range(2)
    ]
    target = 0 if fractions[0] > fractions[1] else 1
    background = counts[target][0][0]
    output_background = counts[1 - target][0][0]

    return [
        [output_background if value == background else 3 for value in row]
        for row in panels[target]
    ]
