            candidates.append((abs(c - (w - 1) / 2), "col", c))

    _, direction, index = min(candidates)

    if direction == "row":
        a, b = grid[:index], grid[index + 1:]
    else:
        a = [row[:index] for row in grid]
        b = [row[index + 1:] for row in grid]

    from collections import Counter
    ca = Counter(v for row in a for v in row)
    cb = Counter(v for row in b for v in row)
    shared = set(ca) & set(cb)
